                // Already in To Do, do nothing
                return;
            }
        }

        if (targetList) {
            targetList.appendChild(card);
            saveBoardState(); // Save after moving
        }
    }

    function saveBoardState() {
        const state = {
            todo: Array.from(todoList.children).map(li => li.textContent),
